example.snippet:
package main

import (
	"context"
)

type MyModule struct{}

func (m *MyModule) Foo(ctx context.Context) (string, error) {
	return dag.Container().
		From("alpine:latest").
		WithEntrypoint([]string{"cat","/etc/os-release"}).
		Publish(ctx, "ttl.sh/my-alpine")
}

from dagger import dag, function, object_type


@object_type
class MyModule:
    @function
    async def foo(self) -> str:
        return (
            await dag.container()
            .from_("alpine:latest")
            .with_entrypoint(["cat", "/etc/os-release"])
            .publish("ttl.sh/my-alpine")
        )

import { dag, object, func } from "@dagger.io/dagger"

@object()
class MyModule {
  @func()
  async foo(): Promise {
    return await dag
      .container()
      .from("alpine:latest")
      .withEntrypoint(["cat", "/etc/os-release"])
      .publish("ttl.sh/my-alpine")
  }
}
